    super8:'<div class="cinematic-art cinematic-art--super8" aria-hidden="true"><div class="super8-gate"><div class="super8-film-window"><div class="super8-film-track"><i class="super8-film-cell super8-film-cell--one"></i><i class="super8-film-cell super8-film-cell--two"></i><i class="super8-film-cell super8-film-cell--three"></i><i class="super8-film-cell super8-film-cell--four"></i></div></div></div><i class="super8-reel super8-reel--one"></i><i class="super8-reel super8-reel--two"></i><i class="super8-shutter"></i><i class="super8-burn"></i></div>',
