    astrolabe10:'<div class="cinematic-art cinematic-art--astrolabe" aria-hidden="true"><i class="astro-orbit astro-orbit--one"></i><i class="astro-orbit astro-orbit--two"></i><i class="astro-orbit astro-orbit--three"></i><i class="astro-meridian"></i><i class="astro-star astro-star--one"></i><i class="astro-star astro-star--two"></i><i class="astro-conjunction"></i></div>',
