function introRuntime(){ return `(()=>{const cfg=JSON.parse(document.querySelector('#wedding-config').textContent),gate=document.querySelector('.wedding-opening'),audio=document.querySelector('[data-music]'),reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;if(!gate)return;const paint=(key,url)=>{if(!url)return;document.querySelectorAll('[data-asset="'+key+'"]').forEach(e=>{e.classList.add('has-asset');e.style.backgroundImage='url('+JSON.stringify(url)+')';e.style.backgroundSize='cover';e.style.backgroundPosition='center'})};paint('hero',cfg.assets?.hero);(cfg.assets?.gallery||[]).forEach((url,index)=>paint('gallery.'+index,url));if(cfg.modules?.intro===false){document.body.classList.remove('gate-open');return}let completed=false;document.addEventListener('click',event=>{if(!event.target.closest('[data-action="open"]')||completed)return;completed=true;gate.classList.add('is-opening');if(audio&&cfg.music?.enabled&&audio.src)audio.volume=0;window.setTimeout(()=>{document.body.classList.remove('gate-open');gate.setAttribute('aria-hidden','true');document.querySelector('.invite')?.classList.add('is-entered');if(audio&&cfg.music?.enabled&&!audio.paused){const target=Math.min(1,Math.max(0,Number(cfg.music.volume)||.35));let step=0;const fade=window.setInterval(()=>{step++;audio.volume=target*Math.min(1,step/18);if(step>=18)window.clearInterval(fade)},55)}},reduced?40:3200)},true)})();`; }
function runtime(){ return `(()=>{const cfg=JSON.parse(document.querySelector('#wedding-config').textContent),get=(o,p)=>p.split('.').reduce((a,k)=>a?.[k],o),toast=m=>{const t=document.querySelector('.toast');t.textContent=m;t.classList.add('show');clearTimeout(window.__tt);window.__tt=setTimeout(()=>t.classList.remove('show'),2500)};document.querySelectorAll('[data-module]').forEach(e=>{if(cfg.modules[e.dataset.module]===false)e.hidden=true});document.querySelectorAll('[data-field]').forEach(e=>{const v=get(cfg.content,e.dataset.field);if(v!==undefined)e.textContent=v});const paint=(key,url)=>{if(!url)return;const e=document.querySelector('[data-asset="'+key+'"]');if(e){e.classList.add('has-asset');e.style.backgroundImage='url('+JSON.stringify(url)+')'}};paint('hero',cfg.assets.hero);cfg.assets.gallery.forEach((u,i)=>paint('gallery.'+i,u));const audio=document.querySelector('[data-music]');if(cfg.music.url){audio.src=cfg.music.url;audio.volume=cfg.music.volume||.35}const gate=document.querySelector('.gate');let opened=false;function begin(){if(opened)return;opened=true;gate.classList.add('is-open');if(cfg.music.enabled&&audio.src)audio.play().catch(()=>{});startAmbient()}document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action;if(a==='open')begin();if(a==='music'){if(audio.paused){audio.play().catch(()=>toast('Chạm lại để phát nhạc'));b.textContent='♫'}else{audio.pause();b.textContent='○'}}if(a==='calendar'){const lines=['BEGIN:VCALENDAR','VERSION:2.0','BEGIN:VEVENT','DTSTART:20261020T093000Z','DTEND:20261020T140000Z','SUMMARY:Wedding','END:VEVENT','END:VCALENDAR'];const x=document.createElement('a');x.href=URL.createObjectURL(new Blob([lines.join('\\r\\n')],{type:'text/calendar'}));x.download='wedding.ics';x.click();toast('Đã tạo lịch cưới mẫu.')}if(a==='map'||a==='registry'||a==='video'){const u=a==='map'?cfg.links?.[b.dataset.link]:a==='registry'?cfg.links?.registry:cfg.assets?.video;if(u)window.open(u,'_blank','noopener');else toast('Thêm URL ở wedding-config để bật liên kết này.')}if(a==='copy'){navigator.clipboard?.writeText(cfg.content.bank);toast('Đã sao chép thông tin mừng cưới.')}if(a==='top')window.scrollTo({top:0,behavior:'smooth'})});document.querySelector('[data-rsvp]').addEventListener('submit',e=>{e.preventDefault();e.currentTarget.querySelector('[data-response]').textContent='Cảm ơn bạn. Phản hồi đã được ghi nhận.';e.currentTarget.reset()});document.querySelector('[data-guestbook]').addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.currentTarget),n=String(f.get('name')||''),w=String(f.get('wish')||'');if(!n||!w)return;const sky=document.querySelector('[data-wishes]');const note=document.createElement('button');note.type='button';note.textContent='✦';note.title=n+': '+w;note.style.cssText='border:0;background:none;color:var(--accent);font-size:28px;margin:5px;animation:pop .45s ease';sky.append(note);e.currentTarget.reset();toast('Lời chúc của bạn đã được gửi vào thiệp.');});const p=document.querySelector('.progress i');window.addEventListener('scroll',()=>{const h=document.documentElement.scrollHeight-innerHeight;p.style.width=(h?scrollY/h*100:0)+'%'},{passive:true});function startAmbient(){if(matchMedia('(prefers-reduced-motion: reduce)').matches)return;const c=document.querySelector('.ambient'),x=c.getContext('2d'),points=Array.from({length:innerWidth<700?22:42},()=>({x:Math.random()*innerWidth,y:Math.random()*innerHeight,r:2+Math.random()*5,v:.15+Math.random()*.35}));function size(){c.width=innerWidth;c.height=innerHeight}size();addEventListener('resize',size,{passive:true});(function draw(){if(!opened)return;x.clearRect(0,0,c.width,c.height);x.fillStyle=getComputedStyle(document.body).getPropertyValue('--accent');points.forEach(q=>{q.y+=q.v;q.x+=Math.sin(q.y*.01)*.2;if(q.y>c.height+10)q.y=-10;x.globalAlpha=.25;x.beginPath();x.arc(q.x,q.y,q.r,0,Math.PI*2);x.fill()});x.globalAlpha=1;requestAnimationFrame(draw)})()}})();`; }

function runtimeRework(){
  return `(()=>{
    const configNode=document.querySelector('#wedding-config');
    const cfg=JSON.parse(configNode?.textContent||'{}');
    const reduced=window.matchMedia?.('(prefers-reduced-motion: reduce)').matches;
    const get=(obj,path)=>String(path||'').split('.').reduce((value,key)=>value?.[key],obj);
    const toast=(message)=>{const node=document.querySelector('.toast');if(!node)return;node.textContent=message;node.classList.add('show');clearTimeout(window.__weddingToast);window.__weddingToast=window.setTimeout(()=>node.classList.remove('show'),2600)};
    const paint=(key,url)=>{if(!url)return;document.querySelectorAll('[data-asset="'+key+'"]').forEach(node=>{node.classList.add('has-asset');node.style.backgroundImage='url('+JSON.stringify(url)+')';node.style.backgroundSize='cover';node.style.backgroundPosition='center'})};
    const modules=cfg.modules||{};
    document.querySelectorAll('[data-module]').forEach(node=>{if(modules[node.dataset.module]===false)node.hidden=true});
    document.querySelectorAll('[data-field]').forEach(node=>{const value=get(cfg.content||{},node.dataset.field);if(value!==undefined)node.textContent=value});
    paint('hero',cfg.assets?.hero);(cfg.assets?.gallery||[]).forEach((url,index)=>paint('gallery.'+index,url));
    const main=document.querySelector('main.invite');
    if(main&&Array.isArray(cfg.order)){const sections=Object.fromEntries([...main.children].filter(node=>node.dataset.module).map(node=>[node.dataset.module,node]));cfg.order.filter(id=>id!=='intro'&&sections[id]).forEach(id=>main.append(sections[id]))}
    const audio=document.querySelector('[data-music]');
    const musicButton=document.querySelector('[data-action="music"]');
    if(cfg.music?.enabled&&cfg.music?.url&&audio){audio.src=cfg.music.url;audio.volume=Number(cfg.music.volume)||.35}else if(musicButton){musicButton.hidden=true}
    const gate=document.querySelector('.wedding-opening');
    let opened=false,ambientStarted=false;
    const weddingISO=String(cfg.content?.dateISO||'2026-10-20');
    const firstTime=String(cfg.content?.events?.[0]?.time||'16:30').match(/\\d{1,2}:\\d{2}/)?.[0]||'16:30';
    const parseDate=(iso,time)=>{const safeTime=String(time||'16:30').padStart(5,'0');return new Date(String(iso).slice(0,10)+'T'+safeTime+':00+07:00')};
    const weddingDate=parseDate(weddingISO,firstTime);if(gate&&cfg.modules?.intro!==false){main?.setAttribute('inert','');main?.setAttribute('aria-hidden','true')}
    const revealPage=()=>gate?.classList.add('is-open');
    const finish=()=>{document.body.classList.remove('gate-open');revealPage();gate?.setAttribute('aria-hidden','true');main?.removeAttribute('inert');main?.removeAttribute('aria-hidden');main?.classList.add('is-entered');main?.querySelector('.scroll-reveal')?.classList.add('is-revealed');startAmbient();if(audio&&cfg.music?.enabled&&!audio.paused){const target=Math.min(1,Math.max(0,Number(cfg.music.volume)||.35));let step=0;const fade=window.setInterval(()=>{step+=1;audio.volume=target*Math.min(1,step/16);if(step>=16)window.clearInterval(fade)},55)}};
    const begin=()=>{if(opened)return;opened=true;gate?.classList.add('is-opening');const openButton=document.querySelector('[data-action="open"]');if(openButton)openButton.disabled=true;if(audio&&cfg.music?.enabled&&audio.src){audio.volume=0;audio.play().catch(()=>{})}window.setTimeout(revealPage,reduced?0:2640);window.setTimeout(finish,reduced?160:3000)};

    const initCountdown=()=>{const node=document.querySelector('[data-countdown]');if(!node)return;const values={days:node.querySelector('[data-countdown-value="days"]'),hours:node.querySelector('[data-countdown-value="hours"]'),minutes:node.querySelector('[data-countdown-value="minutes"]'),seconds:node.querySelector('[data-countdown-value="seconds"]')},status=node.querySelector('[data-countdown-status]');const tick=()=>{let delta=Math.max(0,weddingDate.getTime()-Date.now()),days=Math.floor(delta/86400000);delta-=days*86400000;const hours=Math.floor(delta/3600000);delta-=hours*3600000;const minutes=Math.floor(delta/60000);delta-=minutes*60000;const seconds=Math.floor(delta/1000);Object.entries({days,hours,minutes,seconds}).forEach(([key,value])=>{if(values[key])values[key].textContent=String(value).padStart(2,'0')});if(status)status.textContent=(weddingDate.getTime()<=Date.now())?'Hôm nay là ngày vui của chúng mình':'Mỗi giây đưa chúng mình gần hơn đến ngày hẹn'};tick();window.setInterval(tick,1000)};

    const initCalendar=()=>{const node=document.querySelector('[data-calendar]'),grid=node?.querySelector('[data-calendar-grid]');if(!node||!grid)return;const target=new Date(weddingISO.slice(0,10)+'T12:00:00');const year=target.getFullYear(),month=target.getMonth(),day=target.getDate();const monthName=new Intl.DateTimeFormat('vi-VN',{month:'long'}).format(target).toUpperCase();const monthNode=node.querySelector('[data-calendar-month]'),yearNode=node.querySelector('[data-calendar-year]'),caption=node.querySelector('[data-calendar-caption]');if(monthNode)monthNode.textContent=monthName;if(yearNode)yearNode.textContent=String(year);if(caption)caption.textContent='Ngày cưới · '+String(day).padStart(2,'0')+'/'+String(month+1).padStart(2,'0')+'/'+year;grid.replaceChildren();const offset=(new Date(year,month,1).getDay()+6)%7,totalDays=new Date(year,month+1,0).getDate(),cells=Math.ceil((offset+totalDays)/7)*7;for(let index=0;index<cells;index+=1){const cell=document.createElement('span');cell.className='calendar-day';const current=index-offset+1;if(current<1||current>totalDays){cell.classList.add('is-empty')}else{const time=document.createElement('time');time.dateTime=year+'-'+String(month+1).padStart(2,'0')+'-'+String(current).padStart(2,'0');time.textContent=String(current);cell.append(time);if(current===day){cell.classList.add('is-wedding-day');cell.setAttribute('aria-label','Ngày cưới');const heart=document.createElement('i');heart.setAttribute('aria-hidden','true');heart.textContent='♥';cell.append(heart)}}grid.append(cell)}};

    let wishCarouselApi=null;
    const initWishCarousel=()=>{const carousel=document.querySelector('[data-wish-carousel]'),track=carousel?.querySelector('[data-wish-track]');if(!carousel||!track)return;const position=carousel.querySelector('[data-wish-position]'),toggle=carousel.querySelector('[data-wish-toggle]');let index=0,playing=!reduced,interactionPause=false,timer=null;const slides=()=>[...track.querySelectorAll('[data-wish-slide]')];const setIndex=(next)=>{const all=slides();if(!all.length)return;index=(next+all.length)%all.length;track.style.transform='translate3d(-'+(index*100)+'%,0,0)';all.forEach((slide,i)=>{slide.classList.toggle('is-active',i===index);slide.setAttribute('aria-hidden',i===index?'false':'true')});if(position)position.textContent=String(index+1).padStart(2,'0')+' / '+String(all.length).padStart(2,'0')};const schedule=()=>{window.clearInterval(timer);if(playing&&!interactionPause&&slides().length>1)timer=window.setInterval(()=>setIndex(index+1),5200)};const setInteractionPause=(next)=>{interactionPause=next; schedule()};const add=(name,copy)=>{const slide=document.createElement('article');slide.className='wish-slide';slide.dataset.wishSlide='true';const icon=document.createElement('i');icon.setAttribute('aria-hidden','true');icon.textContent=cfg.content?.monogram||'✦';const quote=document.createElement('blockquote');quote.textContent=copy;const cite=document.createElement('cite');cite.textContent=name;slide.append(icon,quote,cite);track.append(slide);return slide};const seeded=Array.isArray(cfg.content?.wishes)?cfg.content.wishes.filter(item=>item&&(item.copy||item.wish||item.message)):[];if(seeded.length){track.querySelector('[data-wish-placeholder]')?.remove();seeded.forEach(item=>add(String(item.name||'Khách mời'),String(item.copy||item.wish||item.message)))}else if(!slides().length){add('Khách mời','Lời chúc đầu tiên đang chờ bạn viết.')}setIndex(0);schedule();carousel.addEventListener('pointerenter',()=>setInteractionPause(true));carousel.addEventListener('pointerleave',()=>setInteractionPause(false));carousel.addEventListener('focusin',()=>setInteractionPause(true));carousel.addEventListener('focusout',event=>{if(!event.relatedTarget||!carousel.contains(event.relatedTarget))setInteractionPause(false)});if(toggle){toggle.textContent=playing?'Ⅱ':'▶';toggle.setAttribute('aria-pressed',String(playing))}wishCarouselApi={add:(name,copy)=>{const slide=add(name,copy);index=slides().indexOf(slide);setIndex(index);schedule()},prev:()=>{setIndex(index-1);schedule()},next:()=>{setIndex(index+1);schedule()},toggle:()=>{playing=!playing;if(toggle){toggle.textContent=playing?'Ⅱ':'▶';toggle.setAttribute('aria-label',playing?'Tạm dừng tự động':'Bật tự động trượt');toggle.setAttribute('aria-pressed',String(playing))}schedule()}}};
    const initReveal=()=>{const nodes=[...(main?.querySelectorAll('[data-module]')||[])];nodes.forEach((node,index)=>{node.classList.add('scroll-reveal');node.style.setProperty('--reveal-delay',Math.min(index*.045,.3)+'s')});if(reduced||!("IntersectionObserver" in window)){nodes.forEach(node=>node.classList.add('is-revealed'));return}const observer=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('is-revealed');observer.unobserve(entry.target)}}),{rootMargin:'0px 0px -10% 0px',threshold:.12});nodes.forEach(node=>observer.observe(node))};
    initCountdown();initCalendar();initWishCarousel();initReveal();

    const calendarTime=(value,fallback)=>{const match=String(value||fallback).match(/(\\d{1,2}):(\\d{2})/);return match?String(match[1]).padStart(2,'0')+match[2]+'00':'160000'};
    const icsEscape=(value)=>String(value||'').replace(/[\\\\;,]/g,' ');
    const handleAction=(event)=>{const button=event.target.closest?.('[data-action],[data-wish-prev],[data-wish-next],[data-wish-toggle]');if(!button)return;if(button.matches('[data-wish-prev]')){wishCarouselApi?.prev();return}if(button.matches('[data-wish-next]')){wishCarouselApi?.next();return}if(button.matches('[data-wish-toggle]')){wishCarouselApi?.toggle();return}const action=button.dataset.action;if(action==='skip-intro'){if(!opened){opened=true;gate?.classList.add('is-opening');finish()}return}if(action==='open'){begin();return}if(action==='music'&&audio?.src){if(audio.paused){audio.play().catch(()=>toast('Chạm lại để phát nhạc'));button.textContent='♫';button.setAttribute('aria-label','Tắt nhạc')}else{audio.pause();button.textContent='○';button.setAttribute('aria-label','Bật nhạc')}return}if(action==='calendar'){const compact=weddingISO.replace(/-/g,'');const start=compact+'T'+calendarTime(firstTime,'16:30');const end=compact+'T'+calendarTime(cfg.content?.events?.[1]?.time,'18:00');const summary=icsEscape((cfg.content?.bride||'')+' & '+(cfg.content?.groom||'')+' — Wedding');const rows=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//Wedding Invitation//VI','BEGIN:VEVENT','DTSTART;TZID=Asia/Ho_Chi_Minh:'+start,'DTEND;TZID=Asia/Ho_Chi_Minh:'+end,'SUMMARY:'+summary,'LOCATION:'+icsEscape(cfg.content?.city||''),'END:VEVENT','END:VCALENDAR'];const link=document.createElement('a');link.href=URL.createObjectURL(new Blob([rows.join('\\r\\n')],{type:'text/calendar'}));link.download='wedding-'+compact+'.ics';link.click();window.setTimeout(()=>URL.revokeObjectURL(link.href),1000);toast('Đã lưu ngày cưới vào lịch.');return}if(action==='map'||action==='registry'||action==='video'){const url=action==='map'?cfg.links?.[button.dataset.link]:action==='registry'?cfg.links?.registry:cfg.assets?.video;if(url)window.open(url,'_blank','noopener');else toast('Thêm URL ở wedding-config để bật liên kết này.');return}if(action==='copy'){const value=cfg.content?.bank||'';if(navigator.clipboard?.writeText)navigator.clipboard.writeText(value).then(()=>toast('Đã sao chép thông tin mừng cưới.'));else toast(value);return}if(action==='top')window.scrollTo({top:0,behavior:reduced?'auto':'smooth'})};
    document.addEventListener('click',handleAction);
    if(modules.intro===false){if(gate){gate.hidden=true;gate.setAttribute('aria-hidden','true')}opened=true;document.body.classList.remove('gate-open');main?.classList.add('is-entered');startAmbient()}
    const rsvp=document.querySelector('[data-rsvp]');if(rsvp)rsvp.addEventListener('submit',event=>{event.preventDefault();event.currentTarget.querySelector('[data-response]').textContent='Cảm ơn bạn. Phản hồi đã được ghi nhận.';event.currentTarget.reset()});
    const guestbook=document.querySelector('[data-guestbook]');if(guestbook)guestbook.addEventListener('submit',event=>{event.preventDefault();const form=new FormData(event.currentTarget),name=String(form.get('name')||'').trim(),wish=String(form.get('wish')||'').trim();if(!name||!wish)return;wishCarouselApi?.add(name,wish);event.currentTarget.reset();toast('Lời chúc của bạn đã được thêm vào dòng ký ức.')});
    const navLinks=[...document.querySelectorAll('.journey-nav a')],targets=navLinks.map(link=>document.querySelector(link.getAttribute('href'))).filter(Boolean);if('IntersectionObserver' in window&&targets.length){const observer=new IntersectionObserver(entries=>{entries.forEach(entry=>{if(!entry.isIntersecting)return;navLinks.forEach(link=>link.removeAttribute('aria-current'));document.querySelector('.journey-nav a[href="#'+entry.target.id+'"]')?.setAttribute('aria-current','page')})},{rootMargin:'-35% 0px -55%'});targets.forEach(target=>observer.observe(target))}
    function startAmbient(){if(reduced||ambientStarted)return;ambientStarted=true;const canvas=document.querySelector('.ambient'),ctx=canvas?.getContext('2d');if(!ctx)return;const points=Array.from({length:window.innerWidth<700?12:24},()=>({x:Math.random()*window.innerWidth,y:Math.random()*window.innerHeight,r:1+Math.random()*3,v:.12+Math.random()*.24}));const resize=()=>{canvas.width=window.innerWidth;canvas.height=window.innerHeight};resize();window.addEventListener('resize',resize,{passive:true});const draw=()=>{if(!opened)return;ctx.clearRect(0,0,canvas.width,canvas.height);ctx.fillStyle=getComputedStyle(document.body).getPropertyValue('--accent');points.forEach(point=>{point.y+=point.v;point.x+=Math.sin(point.y*.008)*.08;if(point.y>canvas.height+8)point.y=-8;ctx.globalAlpha=.18;ctx.beginPath();ctx.arc(point.x,point.y,point.r,0,Math.PI*2);ctx.fill()});ctx.globalAlpha=1;window.requestAnimationFrame(draw)};draw()}
  })();`;
}

fs.mkdirSync(out,{recursive:true});
for(const t of themes) fs.writeFileSync(path.join(out,`${t.file}.html`),page(t));
console.log(`Built ${themes.length} sample-inspired wedding invitations.`);
